for key, path in links.items(): md = md.replace('('+key+')', '('+(root/path).as_posix()+')')
md = md.replace('TABLE', '\n'.join(table))
fixture_links = []
for probe, prefix, name in [('MpsudValuesDriver','driver_known_values','Токи и напряжение'),
                            ('MpsudValuesCi','ci_known_values','Измерения'),
                            ('MpsudValuesAv','av_edit_wagons77','Ошибка ввода вагонов'),
                            ('MpsudValuesSme','sme_VklTD1','СМЕ при VklTD1')]:
    result, data = selected[probe]
    c = next(c for c in data['captures'] if c['side'] == 'left' and c['label'] == prefix)
    fixture_links.append(f'[{name}]({(result.parent/c["bitmap"]["file"]).as_posix()})')
md = md.replace('FIXTURE_IMAGES', 'Кадры числовых проб: ' + ', '.join(fixture_links) + '.')
md = md.replace('STATS', f'Принято {len(selected)} свежих результатов: {assertions} assertions и {observations} отдельных наблюдений; {captures} кадров и {widgets} чтений полей/виджетов. Нормативная приёмка МПСУиД=false. PASS означает выполнение проверок наблюдаемого поведения, включая воспроизведение описанных дефектов.')
(root / 'dev/docs/MPSUID_SCREENS_RE_AUDIT.md').write_text(md, encoding='utf-8')
print(json.dumps({k:v for k,v in summary.items() if k not in ('results','runs')}, ensure_ascii=False))
